codeExample.code:
-- Create a table
CREATE TABLE Student (
  RollNo  INT PRIMARY KEY,
  Name    VARCHAR(30) NOT NULL,
  Class   INT,
  Marks   DECIMAL(5,2)
);

-- Insert records
INSERT INTO Student VALUES (1, 'Aarav', 12, 95.5);
INSERT INTO Student VALUES (2, 'Priya', 11, 88.0);

-- Select all
SELECT * FROM Student;

-- Update
UPDATE Student SET Marks = 97.0 WHERE RollNo = 1;

-- Delete
DELETE FROM Student WHERE RollNo = 2;

-- Filter with WHERE
SELECT Name, Marks FROM Student WHERE Class = 12;

-- Pattern matching
SELECT Name FROM Student WHERE Name LIKE 'A%';

-- Sorting
SELECT * FROM Student ORDER BY Marks DESC;

-- Aggregation with GROUP BY
SELECT Class, AVG(Marks) AS AvgMarks
FROM Student
GROUP BY Class
HAVING AVG(Marks) > 80;

-- COUNT and DISTINCT
SELECT COUNT(DISTINCT Class) AS Classes FROM Student;

-- Create two tables
CREATE TABLE Dept (
  DeptId   INT PRIMARY KEY,
  DeptName VARCHAR(20)
);

CREATE TABLE Employee (
  EmpId   INT PRIMARY KEY,
  EmpName VARCHAR(30),
  DeptId  INT REFERENCES Dept(DeptId)
);

-- Equi-Join (Inner Join)
SELECT EmpName, DeptName
FROM Employee, Dept
WHERE Employee.DeptId = Dept.DeptId;

-- Using JOIN keyword
SELECT EmpName, DeptName
FROM Employee
INNER JOIN Dept ON Employee.DeptId = Dept.DeptId;
